    { const char * tb_v1266 = "TB_INL void tb_lapic_w(int r, uint32_t v) { tb_lapic[r / 4] = v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1266; }
    { const char * tb_v1267 = "TB_INL uint32_t tb_lapic_r(int r) { return tb_lapic[r / 4]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1267; }
    { const char * tb_v1268 = "// --- ошибки процессора ---\n"; *(const char * *)tb_grow(v_lines) = tb_v1268; }
    { const char * tb_v1269 = "TB_API const char *tb_fault_name[32] = {\"деление на ноль\", \"отладка\", \"NMI\", \"точка останова\", \"переполнение\",\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
    { const char * tb_v1270 = "    \"выход за границы\", \"неизвестная команда\", \"нет FPU\", \"двойная ошибка\", \"\", \"плохой TSS\", \"нет сегмента\",\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "    \"ошибка стека\", \"нарушение защиты\", \"ошибка страницы\", \"\", \"ошибка дробей\", \"выравнивание\", \"проверка железа\", \"ошибка SIMD\"};\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "// клетка (задача background) упала: только она и заканчивается, ядро и другие клетки живут.\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
    { const char * tb_v1273 = "// Тот, кто её запустил, узнаёт это из .crashed (done == 2). Main и прерывание так не умеют:\n"; *(const char * *)tb_grow(v_lines) = tb_v1273; }
    { const char * tb_v1274 = "// их падение останавливает ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v1274; }
    { const char * tb_v1275 = "TB_API int tb_cell_can_fall(void) { return !tb_in_irq && tb_cur != 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1275; }
    { const char * tb_v1276 = "// кто пишет строку: номер задачи + 1 (прерывание — -1, оно не ждёт)\n"; *(const char * *)tb_grow(v_lines) = tb_v1276; }
    { const char * tb_v1277 = "TB_API long long tb_out_me(void) { return tb_in_irq ? -1 : (long long)tb_cur + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1277; }
    { const char * tb_v1278 = "// --- владение памятью (обменная куча, как в старой Омниум): у куска один хозяин — клетка.\n"; *(const char * *)tb_grow(v_lines) = tb_v1278; }
    { const char * tb_v1279 = "// Что уходит из клетки (аргументы background, текст в канале, список через move), становится\n"; *(const char * *)tb_grow(v_lines) = tb_v1279; }
    { const char * tb_v1280 = "// ничьим (метка 0, «ядро») или переходит получателю. Упала клетка — ядро возвращает всё, что\n"; *(const char * *)tb_grow(v_lines) = tb_v1280; }
    { const char * tb_v1281 = "// у неё осталось: этого больше никто не видит.\n"; *(const char * *)tb_grow(v_lines) = tb_v1281; }
    { const char * tb_v1282 = "TB_API int tb_is_piece(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1282; }
    { const char * tb_v1283 = "    const unsigned char *u = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1283; }
    { const char * tb_v1284 = "    if (!p || ((uintptr_t)p & 15) || u < tb_heap + 16 || u >= tb_heap + tb_heap_top) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1284; }
    { const char * tb_v1285 = "    size_t w = *(const size_t *)(u - 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v1285; }
    { const char * tb_v1286 = "    return (w & ~(size_t)0xFF) == TB_HMAGIC && (w & 0xFF) >= 4 && (w & 0xFF) < 32 && ((const uint64_t *)p)[-1] != TB_TAG_FREE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1286; }
    { const char * tb_v1287 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1287; }
    { const char * tb_v1288 = "// кусок становится ничьим (его хозяин больше не платит за него и не утащит при падении)\n"; *(const char * *)tb_grow(v_lines) = tb_v1288; }
    { const char * tb_v1289 = "TB_API void tb_export(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1289; }
    { const char * tb_v1290 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1290; }
    { const char * tb_v1291 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1291; }
    { const char * tb_v1292 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1292; }
    { const char * tb_v1293 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1293; }
    { const char * tb_v1294 = "        *tag = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1294; }
    { const char * tb_v1295 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1295; }
    { const char * tb_v1296 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1296; }
    { const char * tb_v1297 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1297; }
    { const char * tb_v1298 = "// кусок переходит текущей клетке (взяла из канала)\n"; *(const char * *)tb_grow(v_lines) = tb_v1298; }
    { const char * tb_v1299 = "TB_API void tb_adopt(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1299; }
    { const char * tb_v1300 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1300; }
    { const char * tb_v1301 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1301; }
    { const char * tb_v1302 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1302; }
    { const char * tb_v1303 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1303; }
    { const char * tb_v1304 = "        uint64_t t = tb_cell_charge(tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1304; }
    { const char * tb_v1305 = "        *tag = t == (uint64_t)-1 ? 0 : t;   // сверх квоты — пусть будет ничьим, клетку не роняем на приёме\n"; *(const char * *)tb_grow(v_lines) = tb_v1305; }
    { const char * tb_v1306 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1306; }
    { const char * tb_v1307 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1307; }
    { const char * tb_v1308 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1308; }
    { const char * tb_v1309 = "// упала клетка: вернуть все куски с её меткой\n"; *(const char * *)tb_grow(v_lines) = tb_v1309; }
    { const char * tb_v1310 = "TB_API long long tb_cell_reclaim(uint64_t tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1310; }
    { const char * tb_v1311 = "    long long got = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1311; }
    { const char * tb_v1312 = "    if ((tag & 0xFF) == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1312; }
    { const char * tb_v1313 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1313; }
    { const char * tb_v1314 = "    size_t at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1314; }
    { const char * tb_v1315 = "    while (at < tb_heap_top) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1315; }
    { const char * tb_v1316 = "        unsigned char *h = tb_heap + at;\n"; *(const char * *)tb_grow(v_lines) = tb_v1316; }
    { const char * tb_v1317 = "        size_t k = *(size_t *)h & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1317; }
    { const char * tb_v1318 = "        size_t next = at + ((size_t)1 << k) + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1318; }
    { const char * tb_v1319 = "        uint64_t *p = (uint64_t *)(h + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v1319; }
    { const char * tb_v1320 = "        if (p[-1] == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1320; }
    { const char * tb_v1321 = "            got += (long long)((size_t)1 << k);\n"; *(const char * *)tb_grow(v_lines) = tb_v1321; }
    { const char * tb_v1322 = "            p[-1] = TB_TAG_FREE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1322; }
    { const char * tb_v1323 = "            tb_free0(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v1323; }
    { const char * tb_v1324 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1324; }
    { const char * tb_v1325 = "        at = next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1325; }
    { const char * tb_v1326 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1326; }
    { const char * tb_v1327 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1327; }
    { const char * tb_v1328 = "    return got;\n"; *(const char * *)tb_grow(v_lines) = tb_v1328; }
    { const char * tb_v1329 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1329; }
    { const char * tb_v1330 = "TB_API void tb_cell_mark(const char *what, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1330; }
    { const char * tb_v1331 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v1331; }
    { const char * tb_v1332 = "    // замки, которые клетка держала, отпускаем: иначе на них застрянут другие\n"; *(const char * *)tb_grow(v_lines) = tb_v1332; }
    { const char * tb_v1333 = "    for (int i = 0; i < s->nlocks; i++) __atomic_store_n(s->locks[i], 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v1333; }
    { const char * tb_v1334 = "    s->nlocks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1334; }
    { const char * tb_v1335 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v1335; }
    { const char * tb_v1336 = "    if (line > 0) snprintf(buf, sizeof buf, \"*** клетка %d упала: строка %d: %s\\n\", s->no, line, what);\n"; *(const char * *)tb_grow(v_lines) = tb_v1336; }
    { const char * tb_v1337 = "    else snprintf(buf, sizeof buf, \"*** клетка %d упала: %s\\n\", s->no, what);\n"; *(const char * *)tb_grow(v_lines) = tb_v1337; }
    { const char * tb_v1338 = "    fputs(buf, stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v1338; }
    { const char * tb_v1339 = "    tb_cell_reclaim((uint64_t)tb_cur | (s->gen << 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v1339; }
    { const char * tb_v1340 = "    s->mem = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1340; }
    { const char * tb_v1341 = "    s->t->done = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v1341; }
    { const char * tb_v1342 = "    s->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1342; }
    { const char * tb_v1343 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1343; }
    { const char * tb_v1344 = "__attribute__((noreturn)) TB_API void tb_cell_fall(const char *what, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1344; }
    { const char * tb_v1345 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1345; }
    { const char * tb_v1346 = "    tb_cell_mark(what, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v1346; }
    { const char * tb_v1347 = "    tb_bkl_drop();\n"; *(const char * *)tb_grow(v_lines) = tb_v1347; }
    { const char * tb_v1348 = "    for (;;) __asm__ volatile(\"int $48\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1348; }
    { const char * tb_v1349 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1349; }
    { const char * tb_v1350 = "TB_API uint64_t *tb_fault(uint64_t v, uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1350; }
    { const char * tb_v1351 = "    uint64_t rip = f[TB_F_RIP], a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1351; }
    { const char * tb_v1352 = "    const char *what;\n"; *(const char * *)tb_grow(v_lines) = tb_v1352; }
    { const char * tb_v1353 = "    __asm__ volatile(\"movq %%cr2, %0\" : \"=r\"(a));\n"; *(const char * *)tb_grow(v_lines) = tb_v1353; }
    { const char * tb_v1354 = "    if ((v == 14 || v == 8) && tb_is_guard(a)) what = \"стек переполнен: слишком глубокая рекурсия\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1354; }
    { const char * tb_v1355 = "    else if (v == 14 && a < 4096) what = \"обращение по пустому адресу (адрес 0)\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1355; }
    { const char * tb_v1356 = "    else if (v == 14 && (f[TB_F_ERR] & 2) && a >= (uint64_t)(uintptr_t)tb_code_start && a < (uint64_t)(uintptr_t)tb_code_end) what = \"запись в код программы\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1356; }
    { const char * tb_v1357 = "    else if (v == 14) what = \"обращение к памяти, которой нет\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1357; }
    { const char * tb_v1358 = "    else if (v == 8) what = \"двойная ошибка процессора\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1358; }
    { const char * tb_v1359 = "    else what = v < 20 && tb_fault_name[v][0] ? tb_fault_name[v] : \"ошибка процессора\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1359; }
    { const char * tb_v1360 = "    if (tb_cell_can_fall()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1360; }
    { const char * tb_v1361 = "        tb_cell_mark(what, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1361; }
    { const char * tb_v1362 = "        tb_bkl_drop();\n"; *(const char * *)tb_grow(v_lines) = tb_v1362; }
    { const char * tb_v1363 = "        return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1363; }
    { const char * tb_v1364 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1364; }
    { const char * tb_v1365 = "    tb_panic(what, v == 14 || v == 8 ? a : v, rip);\n"; *(const char * *)tb_grow(v_lines) = tb_v1365; }
    { const char * tb_v1366 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1366; }
    { const char * tb_v1367 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1367; }
    { const char * tb_v1368 = "// все прерывания приходят сюда; ответ — кадр, в который вернуться (так переключаются задачи)\n"; *(const char * *)tb_grow(v_lines) = tb_v1368; }
    { const char * tb_v1369 = "__attribute__((used)) static uint64_t *tb_isr(uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1369; }
    { const char * tb_v1370 = "    uint64_t v = f[TB_F_VEC];\n"; *(const char * *)tb_grow(v_lines) = tb_v1370; }
    { const char * tb_v1371 = "    if (v < 32) return tb_fault(v, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1371; }
    { const char * tb_v1372 = "    if (v == 48) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1372; }
    { const char * tb_v1373 = "    if (v == 49) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1373; }
    { const char * tb_v1374 = "        // таймер своего ядра процессора (APIC): 1000 раз в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v1374; }
    { const char * tb_v1375 = "        tb_lapic_w(0xB0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1375; }
    { const char * tb_v1376 = "        if (--tb_me()->slice <= 0) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1376; }
