    { const char * tb_v1378 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1378; }
    { const char * tb_v1379 = "    int irq = (int)v - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v1379; }
    { const char * tb_v1380 = "    if (irq == 0) tb_ms++;\n"; *(const char * *)tb_grow(v_lines) = tb_v1380; }
    { const char * tb_v1381 = "    if (irq == 1) tb_key_irq();\n"; *(const char * *)tb_grow(v_lines) = tb_v1381; }
    { const char * tb_v1382 = "    if (tb_irq_fn[irq]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1382; }
    { const char * tb_v1383 = "        // своя функция прерывания: со своими «переменными потока»\n"; *(const char * *)tb_grow(v_lines) = tb_v1383; }
