    { const char * tb_v1392 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v1392; }
    { const char * tb_v1393 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1393; }
    { const char * tb_v1394 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1394; }
