    { const char * tb_v1854 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1854; }
    { const char * tb_v1855 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1855; }
    { const char * tb_v1856 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1856; }
    { const char * tb_v1857 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1857; }
