    { const char * tb_v2004 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2004; }
    { const char * tb_v2005 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2005; }
    { const char * tb_v2006 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2006; }
    { const char * tb_v2007 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v2007; }
    { const char * tb_v2008 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v2008; }
    { const char * tb_v2009 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v2009; }
    { const char * tb_v2010 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v2010; }
    { const char * tb_v2011 = "TB_API _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2011; }
    { const char * tb_v2012 = "TB_API _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2012; }
    { const char * tb_v2013 = "TB_API int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2013; }
    { const char * tb_v2014 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2014; }
    { const char * tb_v2015 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2015; }
    { const char * tb_v2016 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2016; }
    { const char * tb_v2017 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2017; }
    { const char * tb_v2018 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2018; }
    { const char * tb_v2019 = "TB_API void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2019; }
    { const char * tb_v2020 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v2020; }
    { const char * tb_v2021 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2021; }
    { const char * tb_v2022 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2022; }
    { const char * tb_v2023 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v2023; }
    { const char * tb_v2024 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2024; }
    { const char * tb_v2025 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2025; }
    { const char * tb_v2026 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2026; }
    { const char * tb_v2027 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v2027; }
    { const char * tb_v2028 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2028; }
    { const char * tb_v2029 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2029; }
    { const char * tb_v2030 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2030; }
    { const char * tb_v2031 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2031; }
    { const char * tb_v2032 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v2032; }
    { const char * tb_v2033 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v2033; }
    { const char * tb_v2034 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2034; }
    { const char * tb_v2035 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2035; }
    { const char * tb_v2036 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v2036; }
    { const char * tb_v2037 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2037; }
    { const char * tb_v2038 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2038; }
    { const char * tb_v2039 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2039; }
    { const char * tb_v2040 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v2040; }
    { const char * tb_v2041 = "TB_API _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2041; }
    { const char * tb_v2042 = "TB_API _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2042; }
    { const char * tb_v2043 = "TB_INL tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2043; }
    { const char * tb_v2044 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v2044; }
    { const char * tb_v2045 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2045; }
    { const char * tb_v2046 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v2046; }
    { const char * tb_v2047 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v2047; }
    { const char * tb_v2048 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2048; }
    { const char * tb_v2049 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2049; }
    { const char * tb_v2050 = "    tb_marks[tb_temp_depth] = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v2050; }
    { const char * tb_v2051 = "    tb_temp_depth += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2051; }
    { const char * tb_v2052 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v2052; }
    { const char * tb_v2053 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2053; }
    { const char * tb_v2054 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v2054; }
    { const char * tb_v2055 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2055; }
    { const char * tb_v2056 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2056; }
    { const char * tb_v2057 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v2057; }
    { const char * tb_v2058 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2058; }
    { const char * tb_v2059 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v2059; }
    { const char * tb_v2060 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v2060; }
    { const char * tb_v2061 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v2061; }
    { const char * tb_v2062 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2062; }
    { const char * tb_v2063 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2063; }
    { const char * tb_v2064 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2064; }
    { const char * tb_v2065 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v2065; }
    { const char * tb_v2066 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v2066; }
    { const char * tb_v2067 = "TB_API _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v2067; }
    { const char * tb_v2068 = "TB_API _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v2068; }
    { const char * tb_v2069 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2069; }
    { const char * tb_v2070 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2070; }
    { const char * tb_v2071 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2071; }
    { const char * tb_v2072 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2072; }
    { const char * tb_v2073 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2073; }
    { const char * tb_v2074 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v2074; }
    { const char * tb_v2075 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2075; }
    { const char * tb_v2076 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2076; }
    { const char * tb_v2077 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v2077; }
    { const char * tb_v2078 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2078; }
    { const char * tb_v2079 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v2079; }
    { const char * tb_v2080 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2080; }
    { const char * tb_v2081 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v2081; }
    { const char * tb_v2082 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2082; }
    { const char * tb_v2083 = "TB_INL void tb_temp_end_p(tb_mark *m) { tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2083; }
    { const char * tb_v2084 = "// память функции: своя область, только если функцию позвали не изнутри другой области\n"; *(const char * *)tb_grow(v_lines) = tb_v2084; }
    { const char * tb_v2085 = "TB_INL int tb_fa_begin(tb_mark *m) { if (tb_temp_depth != 0) return 0; *m = tb_temp_begin(); return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2085; }
    { const char * tb_v2086 = "TB_INL void tb_fa_end(int fa, tb_mark *m) { if (fa) tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2086; }
    { const char * tb_v2087 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2087; }
    { const char * tb_v2088 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v2088; }
    { const char * tb_v2089 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2089; }
    { const char * tb_v2090 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v2090; }
    { const char * tb_v2091 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v2091; }
    { const char * tb_v2092 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v2092; }
    { const char * tb_v2093 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v2093; }
    { const char * tb_v2094 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v2094; }
    { const char * tb_v2095 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v2095; }
    { const char * tb_v2096 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v2096; }
    { const char * tb_v2097 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2097; }
    { const char * tb_v2098 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2098; }
    { const char * tb_v2099 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2099; }
    { const char * tb_v2100 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2100; }
    { const char * tb_v2101 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2101; }
    { const char * tb_v2102 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2102; }
    { const char * tb_v2103 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2103; }
    { const char * tb_v2104 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2104; }
    { const char * tb_v2105 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2105; }
    { const char * tb_v2106 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2106; }
    { const char * tb_v2107 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2107; }
    { const char * tb_v2108 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2108; }
    { const char * tb_v2109 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2109; }
    { const char * tb_v2110 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2110; }
    { const char * tb_v2111 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v2111; }
    { const char * tb_v2112 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2112; }
    { const char * tb_v2113 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2113; }
    { const char * tb_v2114 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2114; }
