    { const char * tb_v2116 = "#define TB_GNC 37\n"; *(const char * *)tb_grow(v_lines) = tb_v2116; }
    { const char * tb_v2117 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v2117; }
