    { const char * tb_v2206 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
