    { const char * tb_v2212 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
