    { const char * tb_v2217 = "TB_API tb_gpage *tb_gnewpage(int cls, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "    tb_gpage *pg = calloc(1, sizeof(tb_gpage));\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
