    { const char * tb_v2244 = "    if (i >= pg->nblocks || !(pg->fl[i] & 1)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "    *out = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
    { const char * tb_v2246 = "    return pg->start + i * pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v2246; }
    { const char * tb_v2247 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2247; }
    { const char * tb_v2248 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2248; }
    { const char * tb_v2249 = "TB_API void *tb_galloc_locked(long long n, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2249; }
    { const char * tb_v2250 = "    if (!tb_gready) tb_gsetup();\n"; *(const char * *)tb_grow(v_lines) = tb_v2250; }
    { const char * tb_v2251 = "    if (n <= 0) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2251; }
    { const char * tb_v2252 = "    // +1 байт: адрес «сразу за концом» (так иногда считает C) всё ещё внутри блока\n"; *(const char * *)tb_grow(v_lines) = tb_v2252; }
    { const char * tb_v2253 = "    if (n >= 64) n += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2253; }
    { const char * tb_v2254 = "    if (TB_RARE(tb_gsince >= tb_gnext || tb_gstress) && !tb_goff && tb_gtop &&\n"; *(const char * *)tb_grow(v_lines) = tb_v2254; }
    { const char * tb_v2255 = "        __atomic_load_n(&tb_gthreads, __ATOMIC_ACQUIRE) == 0 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
    { const char * tb_v2256 = "        (tb_gsince >= tb_gnext || (tb_gstress && ++tb_gcount % tb_gstress == 0)))\n"; *(const char * *)tb_grow(v_lines) = tb_v2256; }
    { const char * tb_v2257 = "        tb_gc_collect();\n"; *(const char * *)tb_grow(v_lines) = tb_v2257; }
    { const char * tb_v2258 = "    if (n <= TB_GBIG) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "        int cls = tb_gcls[(n + 7) >> 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
