    { const char * tb_v2655 = "    if (TB_RARE(l->len >= l->cap)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2655; }
    { const char * tb_v2656 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2656; }
    { const char * tb_v2657 = "        long long old = l->cap / 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "        l->cap = l->cap * 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
