    { const char * tb_v2660 = "        memset(l->data + old, 0, l->cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2660; }
    { const char * tb_v2661 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2661; }
