    { const char * tb_v2667 = "    if (l->len == 0) tb_crash(line, \".pop() у пустого списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2667; }
    { const char * tb_v2668 = "    l->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2668; }
