    { const char * tb_v2670 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2670; }
    { const char * tb_v2671 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v2671; }
    { const char * tb_v2672 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2672; }
    { const char * tb_v2673 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2673; }
    { const char * tb_v2674 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2674; }
    { const char * tb_v2675 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2675; }
    { const char * tb_v2676 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2676; }
    { const char * tb_v2677 = "        long long old = l->cap / 8, cap = l->cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2677; }
    { const char * tb_v2678 = "        while (cap < need) cap *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2678; }
    { const char * tb_v2679 = "        l->data = tb_resize(l->data, old, cap / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2679; }
    { const char * tb_v2680 = "        memset(l->data + old, 0, cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2680; }
