    { const char * tb_v2682 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2682; }
    { const char * tb_v2683 = "    unsigned long long *w = (unsigned long long *)l->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2683; }
    { const char * tb_v2684 = "    long long i = l->len;\n"; *(const char * *)tb_grow(v_lines) = tb_v2684; }
    { const char * tb_v2685 = "    for (; i < need && (i & 63); i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2685; }
    { const char * tb_v2686 = "    if (need - i >= 64) { memset(w + (i >> 6), v ? 0xff : 0, ((need - i) >> 6) * 8); i += (need - i) & ~63LL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2686; }
    { const char * tb_v2687 = "    for (; i < need; i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2687; }
    { const char * tb_v2688 = "    l->len = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v2688; }
    { const char * tb_v2689 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2689; }
    { const char * tb_v2690 = "// значения dict bool лежат байтами — в list bool их надо переложить в биты\n"; *(const char * *)tb_grow(v_lines) = tb_v2690; }
    { const char * tb_v2691 = "TB_API tb_list *tb_bits_of_bytes(tb_list *b) { return tb_bits_from(b->len, (const unsigned char *)b->data); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2691; }
    { const char * tb_v2692 = "// N одинаковых элементов в конец (repeat N times: nums.add(0))\n"; *(const char * *)tb_grow(v_lines) = tb_v2692; }
    { const char * tb_v2693 = "TB_API void tb_fill(tb_list *l, long long n, const void *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2693; }
    { const char * tb_v2694 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2694; }
    { const char * tb_v2695 = "    if (l->len + n > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2695; }
    { const char * tb_v2696 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2696; }
    { const char * tb_v2697 = "        long long cap = l->cap * 2 + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2697; }
    { const char * tb_v2698 = "        if (cap < l->len + n) cap = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2698; }
    { const char * tb_v2699 = "        l->data = tb_resize(l->data, l->cap * l->size, cap * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2699; }
    { const char * tb_v2700 = "        l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2700; }
    { const char * tb_v2701 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2701; }
    { const char * tb_v2702 = "    char *p = l->data + l->len * l->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2702; }
    { const char * tb_v2703 = "    int zero = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2703; }
    { const char * tb_v2704 = "    for (long long b = 0; b < l->size; b++) if (((const char *)v)[b]) zero = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2704; }
