    { const char * tb_v3065 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
    { const char * tb_v3066 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3066; }
    { const char * tb_v3067 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3067; }
    { const char * tb_v3068 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v3068; }
    { const char * tb_v3069 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3069; }
    { const char * tb_v3070 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3070; }
    { const char * tb_v3071 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v3071; }
    { const char * tb_v3072 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v3072; }
    { const char * tb_v3073 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v3073; }
    { const char * tb_v3074 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3074; }
    { const char * tb_v3075 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v3075; }
    { const char * tb_v3076 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
    { const char * tb_v3080 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3080; }
    { const char * tb_v3081 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
    { const char * tb_v3087 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
    { const char * tb_v3088 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3088; }
    { const char * tb_v3089 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3089; }
    { const char * tb_v3090 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3090; }
    { const char * tb_v3091 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3091; }
    { const char * tb_v3092 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3092; }
    { const char * tb_v3093 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3093; }
    { const char * tb_v3094 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3094; }
    { const char * tb_v3095 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
    { const char * tb_v3097 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3097; }
    { const char * tb_v3098 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
    { const char * tb_v3099 = "    while ((got = fread(buf + len, 1, cap - len - 1, p)) > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3099; }
    { const char * tb_v3100 = "        len += got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3100; }
    { const char * tb_v3101 = "        if (len + 1 == cap) { buf = tb_resize(buf, cap, cap * 2); cap *= 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3101; }
    { const char * tb_v3102 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3102; }
    { const char * tb_v3103 = "    buf[len] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3103; }
    { const char * tb_v3104 = "    if (pclose(p) != 0) { tb_err = tb_cat(\"не получилось скачать (нет сети, нет curl или сервер ответил ошибкой): \", url); return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3104; }
    { const char * tb_v3105 = "    return buf;\n"; *(const char * *)tb_grow(v_lines) = tb_v3105; }
    { const char * tb_v3106 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3106; }
    { const char * tb_v3107 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3107; }
    { const char * tb_v3108 = "// ---------- JSON: json_get(текст, \"users.0.name\") и json_text(текст) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3108; }
    { const char * tb_v3109 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3109; }
    { const char * tb_v3110 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v3110; }
    { const char * tb_v3111 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3111; }
    { const char * tb_v3112 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3112; }
    { const char * tb_v3113 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v3113; }
    { const char * tb_v3114 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3114; }
    { const char * tb_v3115 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3115; }
    { const char * tb_v3116 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3116; }
    { const char * tb_v3117 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3117; }
    { const char * tb_v3118 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v3118; }
    { const char * tb_v3119 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3119; }
    { const char * tb_v3120 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3120; }
    { const char * tb_v3121 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3121; }
    { const char * tb_v3122 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3122; }
    { const char * tb_v3123 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3123; }
    { const char * tb_v3124 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3124; }
    { const char * tb_v3125 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3125; }
    { const char * tb_v3126 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3126; }
    { const char * tb_v3127 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3127; }
    { const char * tb_v3128 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3128; }
    { const char * tb_v3129 = "    while (*p && *p != ',' && *p != '}' && *p != ']' && *p != ' ' && *p != '\\n' && *p != '\\r' && *p != '\\t') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3129; }
    { const char * tb_v3130 = "    return p == s ? 0 : p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "TB_API int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
    { const char * tb_v3133 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3133; }
    { const char * tb_v3134 = "    for (int i = 0; i < 4; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "        char ch = p[i]; v <<= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
    { const char * tb_v3136 = "        if (ch >= '0' && ch <= '9') v |= ch - '0';\n"; *(const char * *)tb_grow(v_lines) = tb_v3136; }
    { const char * tb_v3137 = "        else if (ch >= 'a' && ch <= 'f') v |= ch - 'a' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v3137; }
    { const char * tb_v3138 = "        else if (ch >= 'A' && ch <= 'F') v |= ch - 'A' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v3138; }
    { const char * tb_v3139 = "        else return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
