    { const char * tb_v3267 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
    { const char * tb_v3268 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v3268; }
    { const char * tb_v3269 = "TB_API long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3269; }
    { const char * tb_v3270 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3270; }
    { const char * tb_v3271 = "    return (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3271; }
    { const char * tb_v3272 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3272; }
    { const char * tb_v3273 = "// цвет с непрозрачностью a: 255 — сплошной (как rgb), 0 — не виден. Рисование смешивает его с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v3273; }
    { const char * tb_v3274 = "TB_API long long tb_rgba(long long r, long long g, long long b, long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3274; }
    { const char * tb_v3275 = "    a = a < 0 ? 0 : a > 255 ? 255 : a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3275; }
    { const char * tb_v3276 = "    return ((255 - a) << 24) | tb_rgb(r, g, b);\n"; *(const char * *)tb_grow(v_lines) = tb_v3276; }
    { const char * tb_v3277 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3277; }
    { const char * tb_v3278 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v3278; }
    { const char * tb_v3279 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3279; }
    { const char * tb_v3280 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3280; }
    { const char * tb_v3281 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3281; }
    { const char * tb_v3282 = "        unsigned lo, hi; __asm__ volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n"; *(const char * *)tb_grow(v_lines) = tb_v3282; }
    { const char * tb_v3283 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3283; }
    { const char * tb_v3284 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3284; }
    { const char * tb_v3285 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v3285; }
    { const char * tb_v3286 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3286; }
    { const char * tb_v3287 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3287; }
    { const char * tb_v3288 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3288; }
    { const char * tb_v3289 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3289; }
    { const char * tb_v3290 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v3290; }
