    { const char * tb_v3321 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
    { const char * tb_v3326 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3326; }
    { const char * tb_v3327 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v3327; }
    { const char * tb_v3328 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v3328; }
    { const char * tb_v3329 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v3329; }
    { const char * tb_v3330 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v3330; }
    { const char * tb_v3331 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
    { const char * tb_v3332 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v3332; }
    { const char * tb_v3333 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3333; }
    { const char * tb_v3334 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3334; }
    { const char * tb_v3335 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3335; }
    { const char * tb_v3336 = "    tb_export(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v3336; }
    { const char * tb_v3337 = "    tb_export(l);\n"; *(const char * *)tb_grow(v_lines) = tb_v3337; }
    { const char * tb_v3338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3338; }
    { const char * tb_v3339 = "TB_API void tb_export_dict(tb_dict *d, int ktext, int vtext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3339; }
    { const char * tb_v3340 = "    if (!d) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3340; }
    { const char * tb_v3341 = "    tb_export_list(d->keys, ktext);\n"; *(const char * *)tb_grow(v_lines) = tb_v3341; }
    { const char * tb_v3342 = "    tb_export_list(d->vals, vtext);\n"; *(const char * *)tb_grow(v_lines) = tb_v3342; }
    { const char * tb_v3343 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3343; }
    { const char * tb_v3344 = "    tb_export(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "    tb_export(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
    { const char * tb_v3347 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3347; }
    { const char * tb_v3348 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3348; }
    { const char * tb_v3349 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
    { const char * tb_v3351 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v3351; }
    { const char * tb_v3352 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3352; }
    { const char * tb_v3353 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3353; }
    { const char * tb_v3354 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3354; }
    { const char * tb_v3355 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3355; }
    { const char * tb_v3356 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3356; }
    { const char * tb_v3357 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3357; }
    { const char * tb_v3358 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3358; }
    { const char * tb_v3359 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3359; }
    { const char * tb_v3360 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
    { const char * tb_v3361 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
    { const char * tb_v3370 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3370; }
    { const char * tb_v3371 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3371; }
    { const char * tb_v3372 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3372; }
    { const char * tb_v3373 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3373; }
    { const char * tb_v3374 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3374; }
    { const char * tb_v3375 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3375; }
    { const char * tb_v3376 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3376; }
    { const char * tb_v3377 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3377; }
    { const char * tb_v3378 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3378; }
    { const char * tb_v3379 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
    { const char * tb_v3381 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3381; }
    { const char * tb_v3382 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3382; }
    { const char * tb_v3383 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v3383; }
    { const char * tb_v3384 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3384; }
    { const char * tb_v3385 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3385; }
    { const char * tb_v3386 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3386; }
    { const char * tb_v3387 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3387; }
    { const char * tb_v3388 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3388; }
    { const char * tb_v3389 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v3389; }
    { const char * tb_v3390 = "TB_API void *tb_dalloc(tb_dict *d, void *old, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3390; }
    { const char * tb_v3391 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v3391; }
    { const char * tb_v3392 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3392; }
    { const char * tb_v3393 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3393; }
    { const char * tb_v3394 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3394; }
    { const char * tb_v3395 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3395; }
    { const char * tb_v3396 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3396; }
    { const char * tb_v3397 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3397; }
    { const char * tb_v3398 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3398; }
    { const char * tb_v3399 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3399; }
    { const char * tb_v3400 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3400; }
    { const char * tb_v3401 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3401; }
    { const char * tb_v3402 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v3402; }
    { const char * tb_v3403 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3403; }
    { const char * tb_v3404 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3404; }
    { const char * tb_v3405 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3405; }
    { const char * tb_v3406 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3406; }
    { const char * tb_v3407 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3407; }
    { const char * tb_v3408 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3408; }
    { const char * tb_v3409 = "        d->slots[i] = (at + 1) | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3409; }
    { const char * tb_v3410 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3410; }
    { const char * tb_v3411 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3411; }
    { const char * tb_v3412 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v3412; }
    { const char * tb_v3413 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3413; }
    { const char * tb_v3414 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3414; }
    { const char * tb_v3415 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3415; }
    { const char * tb_v3416 = "    tb_dreindex(d, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3416; }
    { const char * tb_v3417 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3417; }
    { const char * tb_v3418 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v3418; }
    { const char * tb_v3419 = "TB_API void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3419; }
    { const char * tb_v3420 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3420; }
    { const char * tb_v3421 = "    memset(p, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3421; }
    { const char * tb_v3422 = "    const long long *ks = (const long long *)d->keys->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v3422; }
    { const char * tb_v3423 = "    for (long long at = 0; at < d->keys->len; at++) p[ks[at] - d->base] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3423; }
    { const char * tb_v3424 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3424; }
    { const char * tb_v3425 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3425; }
    { const char * tb_v3426 = "    d->npos = npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v3426; }
    { const char * tb_v3427 = "    d->mode = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3427; }
    { const char * tb_v3428 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3428; }
    { const char * tb_v3429 = "TB_API tb_dict *tb_dict_new(int text, long long vsize) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3429; }
    { const char * tb_v3430 = "    tb_dict *d = tb_mem(sizeof(tb_dict));\n"; *(const char * *)tb_grow(v_lines) = tb_v3430; }
    { const char * tb_v3431 = "    d->text = text;\n"; *(const char * *)tb_grow(v_lines) = tb_v3431; }
    { const char * tb_v3432 = "    d->keys = text ? tb_list_new(sizeof(const char *)) : tb_list_new_np(sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3432; }
    { const char * tb_v3433 = "    d->vals = tb_list_new(vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3433; }
    { const char * tb_v3434 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3434; }
    { const char * tb_v3435 = "    if (text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v3435; }
    { const char * tb_v3436 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3436; }
    { const char * tb_v3437 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3437; }
    { const char * tb_v3438 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
    { const char * tb_v3440 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v3440; }
