    { const char * tb_v3602 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
    { const char * tb_v3612 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
    { const char * tb_v3671 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3671; }
    { const char * tb_v3672 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3672; }
    { const char * tb_v3673 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3673; }
    { const char * tb_v3674 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
    { const char * tb_v3676 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3676; }
    { const char * tb_v3677 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
    { const char * tb_v3688 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "TB_INL long long tb_bnot(long long a) { return ~a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "TB_INL long long tb_shl(long long a, long long n) { return (long long)((unsigned long long)a << (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
    { const char * tb_v3712 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3712; }
    { const char * tb_v3713 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3713; }
    { const char * tb_v3714 = "// shared x += n без замка. В ядре без ОС одно ядро процессора: хватает выключить прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v3714; }
    { const char * tb_v3715 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
    { const char * tb_v3717 = "static inline void tb_atomic_addd(volatile double *p, double v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3717; }
    { const char * tb_v3718 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3718; }
    { const char * tb_v3719 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3719; }
    { const char * tb_v3720 = "// дробь: сравнить и заменить, пока никто не успел поменять\n"; *(const char * *)tb_grow(v_lines) = tb_v3720; }
    { const char * tb_v3721 = "static inline void tb_atomic_addd(volatile double *p, double v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3721; }
    { const char * tb_v3722 = "    volatile uint64_t *q = (volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3722; }
    { const char * tb_v3723 = "    uint64_t old = __atomic_load_n(q, __ATOMIC_SEQ_CST), nw;\n"; *(const char * *)tb_grow(v_lines) = tb_v3723; }
    { const char * tb_v3724 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v3724; }
    { const char * tb_v3725 = "        union { uint64_t u; double d; } a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3725; }
    { const char * tb_v3726 = "        a.u = old; b.d = a.d + v; nw = b.u;\n"; *(const char * *)tb_grow(v_lines) = tb_v3726; }
    { const char * tb_v3727 = "    } while (!__atomic_compare_exchange_n(q, &old, nw, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST));\n"; *(const char * *)tb_grow(v_lines) = tb_v3727; }
    { const char * tb_v3728 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3728; }
    { const char * tb_v3729 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3729; }
    { const char * tb_v3730 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3730; }
    { const char * tb_v3731 = "// ---------- память руками: new_mem, free_mem, grow_mem, copy_mem, fill_mem (только в danger) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3731; }
    { const char * tb_v3732 = "// Перед каждым блоком 16 байт: размер и метка «живой» / «освобождён» — так free_mem ловит чужой\n"; *(const char * *)tb_grow(v_lines) = tb_v3732; }
    { const char * tb_v3733 = "// адрес и второе освобождение. TB_MEM_CHECK=1 (не в ядре): за блоком 16 байт-сторожей, освобождённые\n"; *(const char * *)tb_grow(v_lines) = tb_v3733; }
    { const char * tb_v3734 = "// блоки не отдаются обратно (их чтение и запись ловятся), read/write/copy_mem/fill_mem проверяют\n"; *(const char * *)tb_grow(v_lines) = tb_v3734; }
    { const char * tb_v3735 = "// адрес, а в конце программы печатается, что не освобождено\n"; *(const char * *)tb_grow(v_lines) = tb_v3735; }
    { const char * tb_v3736 = "#define TB_MEM_LIVE 0x4D454D4C49564521ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "#define TB_MEM_DEAD 0x4D454D4445414421ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "#define TB_MEM_GUARD 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
    { const char * tb_v3739 = "typedef struct { uint64_t size, magic; } tb_memh;\n"; *(const char * *)tb_grow(v_lines) = tb_v3739; }
    { const char * tb_v3740 = "typedef struct { uintptr_t a; uint64_t n; int live, line, fline; } tb_memb;\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "TB_API tb_memb *tb_mem_all = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "TB_API long long tb_mem_n = 0, tb_mem_cap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
