    { const char * tb_v3853 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    tb_memh *h = (tb_memh *)(uintptr_t)a - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
    { const char * tb_v3855 = "    if (h->magic == TB_MEM_DEAD) { snprintf(buf, sizeof buf, \"%s: блок уже освобождён\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    if (h->magic != TB_MEM_LIVE) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
    { const char * tb_v3857 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "// TB_MEM_CHECK: блок не отдаётся обратно, а помечается — чтобы поймать чтение после free_mem\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "static void tb_mem_bury(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
