    { const char * tb_v3867 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3867; }
    { const char * tb_v3868 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3868; }
    { const char * tb_v3869 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3869; }
    { const char * tb_v3870 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3870; }
    { const char * tb_v3871 = "    tb_memh *h = tb_mem_own(a, line, \"free_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3871; }
    { const char * tb_v3872 = "    if (tb_memchk()) { tb_mem_bury(a, line); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3872; }
    { const char * tb_v3873 = "    h->magic = TB_MEM_DEAD;\n"; *(const char * *)tb_grow(v_lines) = tb_v3873; }
    { const char * tb_v3874 = "    free(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3874; }
    { const char * tb_v3875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3875; }
    { const char * tb_v3876 = "// grow_mem(адрес, байт): блок нового размера (данные сохраняются, новое место — нули); адрес может стать другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3876; }
    { const char * tb_v3877 = "TB_API long long tb_grow_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3877; }
    { const char * tb_v3878 = "    if (a == 0) return tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3878; }
    { const char * tb_v3879 = "    if (n <= 0) { tb_err = \"grow_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3879; }
    { const char * tb_v3880 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"grow_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3880; }
    { const char * tb_v3881 = "    tb_memh *h = tb_mem_own(a, line, \"grow_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3881; }
    { const char * tb_v3882 = "    uint64_t old = h->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3882; }
    { const char * tb_v3883 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3883; }
    { const char * tb_v3884 = "        long long b = tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3884; }
    { const char * tb_v3885 = "        if (!b) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3885; }
    { const char * tb_v3886 = "        memcpy((void *)(uintptr_t)b, (void *)(uintptr_t)a, (size_t)(old < (uint64_t)n ? old : (uint64_t)n));\n"; *(const char * *)tb_grow(v_lines) = tb_v3886; }
    { const char * tb_v3887 = "        tb_mem_bury(a, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3887; }
    { const char * tb_v3888 = "        return b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3888; }
    { const char * tb_v3889 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3889; }
    { const char * tb_v3890 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3890; }
    { const char * tb_v3891 = "    tb_mem_soft(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3891; }
    { const char * tb_v3892 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3892; }
    { const char * tb_v3893 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3893; }
    { const char * tb_v3894 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3894; }
    { const char * tb_v3895 = "    tb_mem_soft(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3895; }
    { const char * tb_v3896 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3896; }
    { const char * tb_v3897 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3897; }
    { const char * tb_v3898 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v3898; }
    { const char * tb_v3899 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3899; }
    { const char * tb_v3900 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3900; }
    { const char * tb_v3901 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
    { const char * tb_v3905 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3905; }
    { const char * tb_v3906 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3906; }
    { const char * tb_v3907 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3907; }
    { const char * tb_v3908 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3908; }
    { const char * tb_v3909 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3909; }
    { const char * tb_v3910 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3910; }
    { const char * tb_v3911 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3911; }
    { const char * tb_v3912 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3912; }
    { const char * tb_v3913 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3913; }
    { const char * tb_v3914 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3914; }
    { const char * tb_v3915 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3915; }
    { const char * tb_v3916 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3916; }
    { const char * tb_v3917 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3917; }
    { const char * tb_v3918 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3918; }
    { const char * tb_v3919 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3919; }
    { const char * tb_v3920 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3920; }
    { const char * tb_v3921 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3921; }
    { const char * tb_v3922 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3922; }
    { const char * tb_v3923 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3923; }
    { const char * tb_v3924 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3924; }
    { const char * tb_v3925 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3925; }
    { const char * tb_v3926 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3926; }
    { const char * tb_v3927 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3927; }
    { const char * tb_v3928 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3928; }
    { const char * tb_v3929 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3929; }
    { const char * tb_v3930 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3930; }
    { const char * tb_v3931 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3931; }
    { const char * tb_v3932 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3932; }
    { const char * tb_v3933 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3933; }
    { const char * tb_v3934 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3934; }
    { const char * tb_v3935 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3935; }
    { const char * tb_v3936 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3936; }
    { const char * tb_v3937 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3937; }
    { const char * tb_v3938 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3938; }
    { const char * tb_v3939 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3939; }
    { const char * tb_v3940 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3940; }
    { const char * tb_v3941 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3941; }
    { const char * tb_v3942 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3942; }
    { const char * tb_v3943 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3943; }
    { const char * tb_v3944 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3944; }
    { const char * tb_v3945 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v3945; }
    { const char * tb_v3946 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3946; }
    { const char * tb_v3947 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3947; }
    { const char * tb_v3948 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3948; }
    { const char * tb_v3949 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3949; }
    { const char * tb_v3950 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v3950; }
    { const char * tb_v3951 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3951; }
    { const char * tb_v3952 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3952; }
    { const char * tb_v3953 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3953; }
    { const char * tb_v3954 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3954; }
    { const char * tb_v3955 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3955; }
    { const char * tb_v3956 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3956; }
    { const char * tb_v3957 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v3957; }
    { const char * tb_v3958 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3958; }
    { const char * tb_v3959 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3959; }
    { const char * tb_v3960 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3960; }
    { const char * tb_v3961 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3961; }
    { const char * tb_v3962 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v3962; }
    { const char * tb_v3963 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3963; }
    { const char * tb_v3964 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3964; }
    { const char * tb_v3965 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3965; }
    { const char * tb_v3966 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3966; }
    { const char * tb_v3967 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v3967; }
    { const char * tb_v3968 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3968; }
    { const char * tb_v3969 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3969; }
    { const char * tb_v3970 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3970; }
    { const char * tb_v3971 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3971; }
    { const char * tb_v3972 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3972; }
    { const char * tb_v3973 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v3973; }
    { const char * tb_v3974 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3974; }
    { const char * tb_v3975 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3975; }
    { const char * tb_v3976 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3976; }
    { const char * tb_v3977 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3977; }
    { const char * tb_v3978 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3978; }
    { const char * tb_v3979 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3979; }
    { const char * tb_v3980 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3980; }
    { const char * tb_v3981 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v3981; }
    { const char * tb_v3982 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3982; }
    { const char * tb_v3983 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3983; }
    { const char * tb_v3984 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3984; }
    { const char * tb_v3985 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3985; }
    { const char * tb_v3986 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3986; }
    { const char * tb_v3987 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v3987; }
    { const char * tb_v3988 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3988; }
    { const char * tb_v3989 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3989; }
    { const char * tb_v3990 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3990; }
    { const char * tb_v3991 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3991; }
    { const char * tb_v3992 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3992; }
    { const char * tb_v3993 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3993; }
    { const char * tb_v3994 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3994; }
    { const char * tb_v3995 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3995; }
    { const char * tb_v3996 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3996; }
    { const char * tb_v3997 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3997; }
    { const char * tb_v3998 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v3998; }
    { const char * tb_v3999 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3999; }
    { const char * tb_v4000 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v4000; }
    { const char * tb_v4001 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4001; }
    { const char * tb_v4002 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4002; }
    { const char * tb_v4003 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4003; }
    { const char * tb_v4004 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4004; }
    { const char * tb_v4005 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4005; }
    { const char * tb_v4006 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4006; }
    { const char * tb_v4007 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4007; }
    { const char * tb_v4008 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4008; }
    { const char * tb_v4009 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v4009; }
    { const char * tb_v4010 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4010; }
    { const char * tb_v4011 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4011; }
    { const char * tb_v4012 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4012; }
    { const char * tb_v4013 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v4013; }
