    { const char * tb_v4057 = "    uintptr_t p = (uintptr_t)(a + (k >> 20));\n"; *(const char * *)tb_grow(v_lines) = tb_v4057; }
    { const char * tb_v4058 = "    int nb = (int)(k & 15), bo = (int)((k >> 6) & 63), bn = (int)((k >> 12) & 127);\n"; *(const char * *)tb_grow(v_lines) = tb_v4058; }
    { const char * tb_v4059 = "    if (!nb) return (long long)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4059; }
