    { const char * tb_v4078 = "    static const char *uns[9] = { 0, \"число не влезает в поле u8: от 0 до 255\", \"число не влезает в поле u16: от 0 до 65 535\", 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v4078; }
    { const char * tb_v4079 = "        \"число не влезает в поле u32: от 0 до 4 294 967 295\", 0, 0, 0, \"в поле u64 не бывает чисел меньше нуля\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v4079; }
    { const char * tb_v4080 = "    static const char *sig[9] = { 0, \"число не влезает в поле i8: от -128 до 127\", \"число не влезает в поле i16: от -32 768 до 32 767\", 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v4080; }
    { const char * tb_v4081 = "        \"число не влезает в поле i32: от -2 147 483 648 до 2 147 483 647\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4081; }
    { const char * tb_v4082 = "    TB_TOUCH(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4082; }
    { const char * tb_v4083 = "    if (bn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4083; }
    { const char * tb_v4084 = "        if (x < 0 || (bn < 63 && (x >> bn))) tb_crash(line, \"число не влезает в поле bits: от 0 до 2 в степени N без единицы\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4084; }
    { const char * tb_v4085 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
    { const char * tb_v4086 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4086; }
    { const char * tb_v4087 = "        if (k & 32) v = tb_shape_swap(v, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4087; }
    { const char * tb_v4088 = "        v = (v & ~m) | (((uint64_t)x << bo) & m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4088; }
    { const char * tb_v4089 = "        if (k & 32) v = tb_shape_swap(v, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4089; }
