    { const char * tb_v4125 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v4125; }
    { const char * tb_v4126 = "    if (!tb_in_irq)\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
