    { const char * tb_v4435 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4435; }
    { const char * tb_v4436 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4436; }
