    { const char * tb_v4480 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4480; }
    { const char * tb_v4481 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4481; }
    { const char * tb_v4482 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4482; }
    { const char * tb_v4483 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4483; }
    { const char * tb_v4484 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4484; }
