    { const char * tb_v4723 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4723; }
