    { const char * tb_v5002 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5002; }
    { const char * tb_v5003 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5003; }
    { const char * tb_v5004 = "    if (!all || !list) { free(acc); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5004; }
    { const char * tb_v5005 = "    uint32_t *px = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5005; }
    { const char * tb_v5006 = "    for (int j = 0; j < h; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5006; }
    { const char * tb_v5007 = "        float sum = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5007; }
    { const char * tb_v5008 = "        const float *row = acc + (size_t)j * (w + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5008; }
