    { const char * tb_v5014 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5014; }
    { const char * tb_v5015 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5015; }
    { const char * tb_v5016 = "    free(acc);\n"; *(const char * *)tb_grow(v_lines) = tb_v5016; }
    { const char * tb_v5017 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5017; }
    { const char * tb_v5018 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5018; }
    { const char * tb_v5019 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5019; }
    { const char * tb_v5020 = "    c->img = tb_nimg++; c->left = left; c->top = top;\n"; *(const char * *)tb_grow(v_lines) = tb_v5020; }
    { const char * tb_v5021 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5021; }
    { const char * tb_v5022 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5022; }
    { const char * tb_v5023 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v5023; }
    { const char * tb_v5024 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5024; }
    { const char * tb_v5025 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5025; }
    { const char * tb_v5026 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5026; }
    { const char * tb_v5027 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5027; }
    { const char * tb_v5028 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5028; }
    { const char * tb_v5029 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v5029; }
    { const char * tb_v5030 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5030; }
    { const char * tb_v5031 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5031; }
    { const char * tb_v5032 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5032; }
    { const char * tb_v5033 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v5033; }
    { const char * tb_v5034 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5034; }
    { const char * tb_v5035 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5035; }
    { const char * tb_v5036 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5036; }
    { const char * tb_v5037 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5037; }
    { const char * tb_v5038 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5038; }
    { const char * tb_v5039 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5039; }
    { const char * tb_v5040 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5040; }
    { const char * tb_v5041 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5041; }
    { const char * tb_v5042 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5042; }
    { const char * tb_v5043 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5043; }
    { const char * tb_v5044 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5044; }
    { const char * tb_v5045 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5045; }
    { const char * tb_v5046 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5046; }
    { const char * tb_v5047 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5047; }
    { const char * tb_v5048 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5048; }
    { const char * tb_v5049 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v5049; }
    { const char * tb_v5050 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5050; }
    { const char * tb_v5051 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5051; }
    { const char * tb_v5052 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5052; }
    { const char * tb_v5053 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5053; }
    { const char * tb_v5054 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5054; }
    { const char * tb_v5055 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5055; }
    { const char * tb_v5056 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5056; }
    { const char * tb_v5057 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5057; }
    { const char * tb_v5058 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5058; }
    { const char * tb_v5059 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5059; }
    { const char * tb_v5060 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5060; }
    { const char * tb_v5061 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5061; }
    { const char * tb_v5062 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5062; }
    { const char * tb_v5063 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5063; }
    { const char * tb_v5064 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5064; }
    { const char * tb_v5065 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5065; }
    { const char * tb_v5066 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5066; }
    { const char * tb_v5067 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v5067; }
    { const char * tb_v5068 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5068; }
    { const char * tb_v5069 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5069; }
    { const char * tb_v5070 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5070; }
    { const char * tb_v5071 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v5071; }
    { const char * tb_v5072 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5072; }
    { const char * tb_v5073 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5073; }
    { const char * tb_v5074 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5074; }
    { const char * tb_v5075 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5075; }
    { const char * tb_v5076 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5076; }
    { const char * tb_v5077 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5077; }
    { const char * tb_v5078 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5078; }
    { const char * tb_v5079 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5079; }
    { const char * tb_v5080 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5080; }
    { const char * tb_v5081 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5081; }
    { const char * tb_v5082 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5082; }
    { const char * tb_v5083 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5083; }
    { const char * tb_v5084 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5084; }
    { const char * tb_v5085 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5085; }
    { const char * tb_v5086 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5086; }
    { const char * tb_v5087 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v5087; }
    { const char * tb_v5088 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v5088; }
    { const char * tb_v5089 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v5089; }
    { const char * tb_v5090 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5090; }
    { const char * tb_v5091 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5091; }
    { const char * tb_v5092 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v5092; }
    { const char * tb_v5093 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v5093; }
    { const char * tb_v5094 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v5094; }
    { const char * tb_v5095 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5095; }
    { const char * tb_v5096 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v5096; }
    { const char * tb_v5097 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5097; }
    { const char * tb_v5098 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5098; }
    { const char * tb_v5099 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v5099; }
    { const char * tb_v5100 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v5100; }
    { const char * tb_v5101 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5101; }
    { const char * tb_v5102 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5102; }
    { const char * tb_v5103 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v5103; }
    { const char * tb_v5104 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v5104; }
    { const char * tb_v5105 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v5105; }
    { const char * tb_v5106 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v5106; }
    { const char * tb_v5107 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5107; }
    { const char * tb_v5108 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5108; }
    { const char * tb_v5109 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v5109; }
    { const char * tb_v5110 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5110; }
    { const char * tb_v5111 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v5111; }
    { const char * tb_v5112 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v5112; }
    { const char * tb_v5113 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5113; }
    { const char * tb_v5114 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v5114; }
    { const char * tb_v5115 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v5115; }
    { const char * tb_v5116 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5116; }
    { const char * tb_v5117 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v5117; }
    { const char * tb_v5118 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5118; }
    { const char * tb_v5119 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v5119; }
    { const char * tb_v5120 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5120; }
    { const char * tb_v5121 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5121; }
    { const char * tb_v5122 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5122; }
    { const char * tb_v5123 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v5123; }
    { const char * tb_v5124 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5124; }
    { const char * tb_v5125 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v5125; }
    { const char * tb_v5126 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5126; }
    { const char * tb_v5127 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5127; }
    { const char * tb_v5128 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5128; }
    { const char * tb_v5129 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v5129; }
    { const char * tb_v5130 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5130; }
    { const char * tb_v5131 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5131; }
    { const char * tb_v5132 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v5132; }
    { const char * tb_v5133 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5133; }
    { const char * tb_v5134 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v5134; }
    { const char * tb_v5135 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v5135; }
