    { const char * tb_v5167 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5167; }
    { const char * tb_v5168 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5168; }
    { const char * tb_v5169 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5169; }
    { const char * tb_v5170 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5170; }
    { const char * tb_v5171 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5171; }
    { const char * tb_v5172 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5172; }
    { const char * tb_v5173 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5173; }
    { const char * tb_v5174 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5174; }
    { const char * tb_v5175 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5175; }
