    { const char * tb_v5178 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5178; }
    { const char * tb_v5179 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5179; }
    { const char * tb_v5180 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5180; }
    { const char * tb_v5181 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5181; }
    { const char * tb_v5182 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5182; }
    { const char * tb_v5183 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5183; }
    { const char * tb_v5184 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5184; }
    { const char * tb_v5185 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5185; }
    { const char * tb_v5186 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v5186; }
    { const char * tb_v5187 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5187; }
    { const char * tb_v5188 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5188; }
    { const char * tb_v5189 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5189; }
    { const char * tb_v5190 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5190; }
    { const char * tb_v5191 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5191; }
    { const char * tb_v5192 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5192; }
    { const char * tb_v5193 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5193; }
    { const char * tb_v5194 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5194; }
