    { const char * tb_v7742 = "// window_sharp в X11: масштаб из настройки Xft.dpi (её ставят GNOME и KDE), иначе 1\n"; *(const char * *)tb_grow(v_lines) = tb_v7742; }
    { const char * tb_v7743 = "TB_API double tb_gfx_scale(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7743; }
    { const char * tb_v7744 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7744; }
    { const char * tb_v7745 = "    if (!tb_dpy) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7745; }
