    { const char * tb_v7755 = "    tb_xgc = XCreateGC(tb_dpy, tb_xw, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7755; }
    { const char * tb_v7756 = "    XSelectInput(tb_dpy, tb_xw, ExposureMask | KeyPressMask | KeyReleaseMask | ButtonPressMask | ButtonReleaseMask | PointerMotionMask | StructureNotifyMask);\n"; *(const char * *)tb_grow(v_lines) = tb_v7756; }
    { const char * tb_v7757 = "    tb_x_hints(tb_gw, tb_gh, tb_gw, tb_gh);   // размер окна не меняется, пока программа не спросит window_w()\n"; *(const char * *)tb_grow(v_lines) = tb_v7757; }
