    { const char * tb_v7763 = "    tb_ximg = XCreateImage(tb_dpy, DefaultVisual(tb_dpy, scr), 24, ZPixmap, 0, (char *)tb_px, tb_gw, tb_gh, 32, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7763; }
    { const char * tb_v7764 = "    if (tb_gpu_want()) tb_gpu_on = tb_vk_init(\"VK_KHR_xlib_surface\", tb_x_surface);\n"; *(const char * *)tb_grow(v_lines) = tb_v7764; }
