    { const char * tb_v7769 = "// знак клавиши → буква Unicode (русская раскладка в X11 — свои старые номера 0x6c0..0x6ff)\n"; *(const char * *)tb_grow(v_lines) = tb_v7769; }
    { const char * tb_v7770 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7770; }
    { const char * tb_v7771 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v7771; }
    { const char * tb_v7772 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7772; }
    { const char * tb_v7773 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v7773; }
    { const char * tb_v7774 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7774; }
    { const char * tb_v7775 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v7775; }
    { const char * tb_v7776 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v7776; }
    { const char * tb_v7777 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7777; }
    { const char * tb_v7778 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7778; }
    { const char * tb_v7779 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7779; }
    { const char * tb_v7780 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v7780; }
    { const char * tb_v7781 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v7781; }
    { const char * tb_v7782 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7782; }
    { const char * tb_v7783 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7783; }
    { const char * tb_v7784 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v7784; }
    { const char * tb_v7785 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v7785; }
    { const char * tb_v7786 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7786; }
    { const char * tb_v7787 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7787; }
    { const char * tb_v7788 = "    case XK_Control_L: case XK_Control_R: return TB_K_CTRL;\n"; *(const char * *)tb_grow(v_lines) = tb_v7788; }
    { const char * tb_v7789 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7789; }
    { const char * tb_v7790 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v7790; }
    { const char * tb_v7791 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v7791; }
    { const char * tb_v7792 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7792; }
    { const char * tb_v7793 = "    if (s >= XK_F1 && s <= XK_F12) return TB_K_F1 + (int)(s - XK_F1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7793; }
    { const char * tb_v7794 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v7794; }
    { const char * tb_v7795 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7795; }
    { const char * tb_v7796 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7796; }
    { const char * tb_v7797 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v7797; }
    { const char * tb_v7798 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7798; }
    { const char * tb_v7799 = "TB_API void tb_x_clip_answer(XSelectionRequestEvent *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7799; }
    { const char * tb_v7800 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7800; }
    { const char * tb_v7801 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v7801; }
    { const char * tb_v7802 = "    memset(&ev, 0, sizeof ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7802; }
    { const char * tb_v7803 = "    ev.type = SelectionNotify; ev.display = r->display; ev.requestor = r->requestor;\n"; *(const char * *)tb_grow(v_lines) = tb_v7803; }
    { const char * tb_v7804 = "    ev.selection = r->selection; ev.target = r->target; ev.time = r->time; ev.property = None;\n"; *(const char * *)tb_grow(v_lines) = tb_v7804; }
    { const char * tb_v7805 = "    Atom prop = r->property ? r->property : r->target;\n"; *(const char * *)tb_grow(v_lines) = tb_v7805; }
    { const char * tb_v7806 = "    if (r->target == targets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7806; }
    { const char * tb_v7807 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v7807; }
    { const char * tb_v7808 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7808; }
    { const char * tb_v7809 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7809; }
    { const char * tb_v7810 = "    } else if ((r->target == utf8 || r->target == XA_STRING) && tb_x_clip) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7810; }
    { const char * tb_v7811 = "        XChangeProperty(tb_dpy, r->requestor, prop, r->target, 8, PropModeReplace, (unsigned char *)tb_x_clip, (int)strlen(tb_x_clip));\n"; *(const char * *)tb_grow(v_lines) = tb_v7811; }
    { const char * tb_v7812 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7812; }
    { const char * tb_v7813 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7813; }
    { const char * tb_v7814 = "    XSendEvent(tb_dpy, r->requestor, False, 0, (XEvent *)&ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7814; }
    { const char * tb_v7815 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7815; }
    { const char * tb_v7816 = "TB_API void tb_gfx_clip_set(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7816; }
    { const char * tb_v7817 = "    free(tb_x_clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7817; }
    { const char * tb_v7818 = "    tb_x_clip = strdup(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v7818; }
    { const char * tb_v7819 = "    if (!tb_dpy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7819; }
    { const char * tb_v7820 = "    XSetSelectionOwner(tb_dpy, XInternAtom(tb_dpy, \"CLIPBOARD\", False), tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7820; }
    { const char * tb_v7821 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7821; }
    { const char * tb_v7822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7822; }
    { const char * tb_v7823 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7823; }
    { const char * tb_v7824 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7824; }
    { const char * tb_v7825 = "    Atom clip = XInternAtom(tb_dpy, \"CLIPBOARD\", False), utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7825; }
    { const char * tb_v7826 = "    Window owner = XGetSelectionOwner(tb_dpy, clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7826; }
    { const char * tb_v7827 = "    if (owner == tb_xw) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7827; }
    { const char * tb_v7828 = "    if (owner == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7828; }
    { const char * tb_v7829 = "    Atom prop = XInternAtom(tb_dpy, \"TACHBIT_CLIP\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7829; }
    { const char * tb_v7830 = "    XConvertSelection(tb_dpy, clip, utf8, prop, tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7830; }
    { const char * tb_v7831 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7831; }
    { const char * tb_v7832 = "    // ждём ответ владельца не дольше полсекунды; чужие события по дороге не теряем\n"; *(const char * *)tb_grow(v_lines) = tb_v7832; }
    { const char * tb_v7833 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v7833; }
    { const char * tb_v7834 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7834; }
    { const char * tb_v7835 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7835; }
    { const char * tb_v7836 = "        if (XCheckTypedWindowEvent(tb_dpy, tb_xw, SelectionNotify, &e)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7836; }
    { const char * tb_v7837 = "            if (e.xselection.property == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7837; }
    { const char * tb_v7838 = "            Atom type; int fmt; unsigned long n = 0, rest = 0; unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7838; }
    { const char * tb_v7839 = "            XGetWindowProperty(tb_dpy, tb_xw, prop, 0, 1 << 24, True, AnyPropertyType, &type, &fmt, &n, &rest, &data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7839; }
    { const char * tb_v7840 = "            char *out = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7840; }
    { const char * tb_v7841 = "            if (data && fmt == 8) { out = malloc(n + 1); if (out) { memcpy(out, data, n); out[n] = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v7841; }
    { const char * tb_v7842 = "            if (data) XFree(data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7842; }
    { const char * tb_v7843 = "            return out;\n"; *(const char * *)tb_grow(v_lines) = tb_v7843; }
    { const char * tb_v7844 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7844; }
    { const char * tb_v7845 = "        if (XCheckTypedEvent(tb_dpy, SelectionRequest, &e)) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v7845; }
    { const char * tb_v7846 = "        struct timespec ts = { 0, 2000000 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7846; }
    { const char * tb_v7847 = "        nanosleep(&ts, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7847; }
    { const char * tb_v7848 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7848; }
