    { const char * tb_v8026 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8026; }
    { const char * tb_v8027 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8027; }
    { const char * tb_v8028 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v8028; }
    { const char * tb_v8029 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v8029; }
