    { const char * tb_v8040 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8040; }
    { const char * tb_v8041 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v8041; }
    { const char * tb_v8042 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8042; }
    { const char * tb_v8043 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8043; }
    { const char * tb_v8044 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8044; }
    { const char * tb_v8045 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v8045; }
    { const char * tb_v8046 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v8046; }
    { const char * tb_v8047 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8047; }
    { const char * tb_v8048 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8048; }
    { const char * tb_v8049 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8049; }
    { const char * tb_v8050 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8050; }
    { const char * tb_v8051 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8051; }
    { const char * tb_v8052 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8052; }
    { const char * tb_v8053 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8053; }
    { const char * tb_v8054 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8054; }
    { const char * tb_v8055 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8055; }
    { const char * tb_v8056 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8056; }
    { const char * tb_v8057 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8057; }
