    { const char * tb_v8060 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8060; }
    { const char * tb_v8061 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v8061; }
    { const char * tb_v8062 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8062; }
    { const char * tb_v8063 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8063; }
    { const char * tb_v8064 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8064; }
    { const char * tb_v8065 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8065; }
    { const char * tb_v8066 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8066; }
    { const char * tb_v8067 = "    uint32_t *p = &tb_px[y * tb_gw + x];\n"; *(const char * *)tb_grow(v_lines) = tb_v8067; }
    { const char * tb_v8068 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8068; }
    { const char * tb_v8069 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8069; }
    { const char * tb_v8070 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v8070; }
    { const char * tb_v8071 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8071; }
    { const char * tb_v8072 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v8072; }
    { const char * tb_v8073 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8073; }
    { const char * tb_v8074 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v8074; }
    { const char * tb_v8075 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8075; }
    { const char * tb_v8076 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8076; }
    { const char * tb_v8077 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8077; }
    { const char * tb_v8078 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8078; }
    { const char * tb_v8079 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8079; }
    { const char * tb_v8080 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8080; }
    { const char * tb_v8081 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8081; }
    { const char * tb_v8082 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v8082; }
    { const char * tb_v8083 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8083; }
    { const char * tb_v8084 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v8084; }
    { const char * tb_v8085 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8085; }
    { const char * tb_v8086 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v8086; }
    { const char * tb_v8087 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8087; }
    { const char * tb_v8088 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8088; }
    { const char * tb_v8089 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v8089; }
    { const char * tb_v8090 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8090; }
    { const char * tb_v8091 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8091; }
    { const char * tb_v8092 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8092; }
    { const char * tb_v8093 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v8093; }
    { const char * tb_v8094 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8094; }
    { const char * tb_v8095 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8095; }
    { const char * tb_v8096 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8096; }
    { const char * tb_v8097 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8097; }
    { const char * tb_v8098 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8098; }
    { const char * tb_v8099 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8099; }
    { const char * tb_v8100 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8100; }
    { const char * tb_v8101 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8101; }
    { const char * tb_v8102 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8102; }
    { const char * tb_v8103 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8103; }
    { const char * tb_v8104 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v8104; }
    { const char * tb_v8105 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v8105; }
    { const char * tb_v8106 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v8106; }
    { const char * tb_v8107 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8107; }
    { const char * tb_v8108 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8108; }
    { const char * tb_v8109 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v8109; }
    { const char * tb_v8110 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8110; }
    { const char * tb_v8111 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8111; }
    { const char * tb_v8112 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v8112; }
    { const char * tb_v8113 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8113; }
    { const char * tb_v8114 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8114; }
    { const char * tb_v8115 = "            double cx = side ? x + w - r - 0.5 : x + r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v8115; }
    { const char * tb_v8116 = "            long long i0 = side ? x + w - r : x, i1 = side ? x + w : x + r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8116; }
    { const char * tb_v8117 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8117; }
