    { const char * tb_v8125 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v8125; }
    { const char * tb_v8126 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8126; }
    { const char * tb_v8127 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8127; }
    { const char * tb_v8128 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8128; }
    { const char * tb_v8129 = "    long long W = x1 - x0, H = y1 - y0, n = W > H ? W : H;\n"; *(const char * *)tb_grow(v_lines) = tb_v8129; }
