    { const char * tb_v8136 = "            for (long long o = 0; o < outer; o++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8136; }
    { const char * tb_v8137 = "                // строка (или столбец) — во временный ряд, потом скользящая сумма окна 2r+1\n"; *(const char * *)tb_grow(v_lines) = tb_v8137; }
    { const char * tb_v8138 = "                for (long long k = 0; k < len; k++) line[k] = dir ? tb_px[(y0 + k) * tb_gw + x0 + o] : tb_px[(y0 + o) * tb_gw + x0 + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8138; }
    { const char * tb_v8139 = "                long long sr = 0, sg = 0, sb = 0, win = 2 * r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8139; }
    { const char * tb_v8140 = "                for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8140; }
