    { const char * tb_v8142 = "                    sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8142; }
    { const char * tb_v8143 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8143; }
    { const char * tb_v8144 = "                for (long long k = 0; k < len; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8144; }
    { const char * tb_v8145 = "                    uint32_t v = (uint32_t)((sr / win) << 16 | (sg / win) << 8 | (sb / win));\n"; *(const char * *)tb_grow(v_lines) = tb_v8145; }
    { const char * tb_v8146 = "                    if (dir) tb_px[(y0 + k) * tb_gw + x0 + o] = v; else tb_px[(y0 + o) * tb_gw + x0 + k] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8146; }
    { const char * tb_v8147 = "                    uint32_t out = line[k - r < 0 ? 0 : k - r], in = line[k + r + 1 >= len ? len - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8147; }
    { const char * tb_v8148 = "                    sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8148; }
    { const char * tb_v8149 = "                    sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8149; }
    { const char * tb_v8150 = "                    sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8150; }
    { const char * tb_v8151 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8151; }
    { const char * tb_v8152 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8152; }
    { const char * tb_v8153 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8153; }
    { const char * tb_v8154 = "    free(line);\n"; *(const char * *)tb_grow(v_lines) = tb_v8154; }
    { const char * tb_v8155 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8155; }
    { const char * tb_v8156 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8156; }
    { const char * tb_v8157 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8157; }
