    { const char * tb_v8169 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8169; }
    { const char * tb_v8170 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8170; }
    { const char * tb_v8171 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8171; }
    { const char * tb_v8172 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8172; }
    { const char * tb_v8173 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v8173; }
