    { const char * tb_v8176 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8176; }
    { const char * tb_v8177 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v8177; }
    { const char * tb_v8178 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v8178; }
    { const char * tb_v8179 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8179; }
