    { const char * tb_v8216 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
    { const char * tb_v8218 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v8218; }
    { const char * tb_v8219 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8219; }
    { const char * tb_v8220 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8220; }
    { const char * tb_v8221 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8221; }
    { const char * tb_v8222 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8222; }
    { const char * tb_v8223 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8223; }
    { const char * tb_v8224 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8224; }
    { const char * tb_v8225 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8225; }
    { const char * tb_v8226 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8226; }
    { const char * tb_v8227 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
    { const char * tb_v8229 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8229; }
    { const char * tb_v8230 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8230; }
    { const char * tb_v8231 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8231; }
    { const char * tb_v8232 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8232; }
    { const char * tb_v8233 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8233; }
    { const char * tb_v8234 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8234; }
    { const char * tb_v8235 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8235; }
    { const char * tb_v8236 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v8236; }
    { const char * tb_v8237 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8237; }
    { const char * tb_v8238 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8238; }
    { const char * tb_v8239 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8239; }
    { const char * tb_v8240 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8240; }
    { const char * tb_v8241 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8241; }
    { const char * tb_v8242 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8242; }
    { const char * tb_v8243 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8243; }
    { const char * tb_v8244 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8244; }
    { const char * tb_v8245 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8245; }
    { const char * tb_v8246 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8246; }
    { const char * tb_v8247 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8247; }
    { const char * tb_v8248 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8248; }
    { const char * tb_v8249 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8249; }
    { const char * tb_v8250 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v8250; }
    { const char * tb_v8251 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v8251; }
    { const char * tb_v8252 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8252; }
    { const char * tb_v8253 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8253; }
    { const char * tb_v8254 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8254; }
    { const char * tb_v8255 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8255; }
    { const char * tb_v8256 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8256; }
    { const char * tb_v8257 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8257; }
    { const char * tb_v8258 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8258; }
    { const char * tb_v8259 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8259; }
    { const char * tb_v8260 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8260; }
    { const char * tb_v8261 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v8261; }
    { const char * tb_v8262 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8262; }
    { const char * tb_v8263 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v8263; }
    { const char * tb_v8264 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8264; }
    { const char * tb_v8265 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8265; }
    { const char * tb_v8266 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8266; }
    { const char * tb_v8267 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8267; }
    { const char * tb_v8268 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v8268; }
    { const char * tb_v8269 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8269; }
    { const char * tb_v8270 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8270; }
    { const char * tb_v8271 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v8271; }
    { const char * tb_v8272 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8272; }
    { const char * tb_v8273 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8273; }
    { const char * tb_v8274 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8274; }
    { const char * tb_v8275 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v8275; }
    { const char * tb_v8276 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8276; }
    { const char * tb_v8277 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8277; }
    { const char * tb_v8278 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8278; }
    { const char * tb_v8279 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v8279; }
    { const char * tb_v8280 = "    for (int i = 0; i < n; i++) { rx[i] = tb_rnd(ax[i]); ry[i] = tb_rnd(ay[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8280; }
    { const char * tb_v8281 = "    for (int i = 1; i + 1 < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8281; }
    { const char * tb_v8282 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v8282; }
    { const char * tb_v8283 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8283; }
    { const char * tb_v8284 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8284; }
    { const char * tb_v8285 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8285; }
    { const char * tb_v8286 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8286; }
    { const char * tb_v8287 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8287; }
    { const char * tb_v8288 = "    long long t[6] = { x1, y1, x2, y2, x3, y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8288; }
    { const char * tb_v8289 = "    int big = 0;   // (не far/near: на Windows это пустые слова из windows.h)\n"; *(const char * *)tb_grow(v_lines) = tb_v8289; }
    { const char * tb_v8290 = "    for (int i = 0; i < 6; i++) if (t[i] < -8192 || t[i] > 8192) big = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8290; }
    { const char * tb_v8291 = "    if (!big) { tb_tri_draw_i(t, c, 0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8291; }
    { const char * tb_v8292 = "    double px[3] = { (double)x1, (double)x2, (double)x3 }, py[3] = { (double)y1, (double)y2, (double)y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8292; }
    { const char * tb_v8293 = "    tb_poly_draw(px, py, 3, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8293; }
    { const char * tb_v8294 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8294; }
    { const char * tb_v8295 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v8295; }
    { const char * tb_v8296 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8296; }
    { const char * tb_v8297 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8297; }
    { const char * tb_v8298 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8298; }
    { const char * tb_v8299 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8299; }
    { const char * tb_v8300 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8300; }
    { const char * tb_v8301 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8301; }
    { const char * tb_v8302 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8302; }
    { const char * tb_v8303 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8303; }
    { const char * tb_v8304 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8304; }
    { const char * tb_v8305 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8305; }
    { const char * tb_v8306 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8306; }
    { const char * tb_v8307 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8307; }
    { const char * tb_v8308 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8308; }
    { const char * tb_v8309 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8309; }
    { const char * tb_v8310 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v8310; }
    { const char * tb_v8311 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v8311; }
    { const char * tb_v8312 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8312; }
    { const char * tb_v8313 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8313; }
    { const char * tb_v8314 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8314; }
    { const char * tb_v8315 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8315; }
    { const char * tb_v8316 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8316; }
    { const char * tb_v8317 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8317; }
    { const char * tb_v8318 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8318; }
    { const char * tb_v8319 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8319; }
    { const char * tb_v8320 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8320; }
    { const char * tb_v8321 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v8321; }
    { const char * tb_v8322 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8322; }
    { const char * tb_v8323 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8323; }
    { const char * tb_v8324 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8324; }
    { const char * tb_v8325 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8325; }
    { const char * tb_v8326 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8326; }
    { const char * tb_v8327 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8327; }
    { const char * tb_v8328 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8328; }
    { const char * tb_v8329 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8329; }
    { const char * tb_v8330 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8330; }
    { const char * tb_v8331 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8331; }
    { const char * tb_v8332 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8332; }
    { const char * tb_v8333 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8333; }
    { const char * tb_v8334 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8334; }
    { const char * tb_v8335 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v8335; }
    { const char * tb_v8336 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8336; }
    { const char * tb_v8337 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8337; }
    { const char * tb_v8338 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8338; }
    { const char * tb_v8339 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8339; }
    { const char * tb_v8340 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v8340; }
    { const char * tb_v8341 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8341; }
    { const char * tb_v8342 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8342; }
    { const char * tb_v8343 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v8343; }
    { const char * tb_v8344 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8344; }
    { const char * tb_v8345 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v8345; }
    { const char * tb_v8346 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v8346; }
    { const char * tb_v8347 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8347; }
    { const char * tb_v8348 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v8348; }
    { const char * tb_v8349 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v8349; }
    { const char * tb_v8350 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v8350; }
    { const char * tb_v8351 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8351; }
    { const char * tb_v8352 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8352; }
    { const char * tb_v8353 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v8353; }
    { const char * tb_v8354 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v8354; }
    { const char * tb_v8355 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v8355; }
    { const char * tb_v8356 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v8356; }
    { const char * tb_v8357 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v8357; }
    { const char * tb_v8358 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v8358; }
    { const char * tb_v8359 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v8359; }
    { const char * tb_v8360 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8360; }
    { const char * tb_v8361 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v8361; }
    { const char * tb_v8362 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8362; }
    { const char * tb_v8363 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8363; }
    { const char * tb_v8364 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8364; }
    { const char * tb_v8365 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8365; }
    { const char * tb_v8366 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8366; }
    { const char * tb_v8367 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8367; }
    { const char * tb_v8368 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8368; }
    { const char * tb_v8369 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v8369; }
    { const char * tb_v8370 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v8370; }
    { const char * tb_v8371 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8371; }
    { const char * tb_v8372 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8372; }
    { const char * tb_v8373 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v8373; }
    { const char * tb_v8374 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8374; }
    { const char * tb_v8375 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8375; }
    { const char * tb_v8376 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v8376; }
    { const char * tb_v8377 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v8377; }
    { const char * tb_v8378 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v8378; }
    { const char * tb_v8379 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v8379; }
