    { const char * tb_v8650 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8650; }
    { const char * tb_v8651 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v8651; }
    { const char * tb_v8652 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8652; }
    { const char * tb_v8653 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v8653; }
    { const char * tb_v8654 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v8654; }
    { const char * tb_v8655 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8655; }
    { const char * tb_v8656 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v8656; }
    { const char * tb_v8657 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8657; }
    { const char * tb_v8658 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8658; }
    { const char * tb_v8659 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v8659; }
    { const char * tb_v8660 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8660; }
    { const char * tb_v8661 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8661; }
    { const char * tb_v8662 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v8662; }
    { const char * tb_v8663 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v8663; }
    { const char * tb_v8664 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8664; }
    { const char * tb_v8665 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v8665; }
    { const char * tb_v8666 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8666; }
    { const char * tb_v8667 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8667; }
