    { const char * tb_v8674 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8674; }
