    { const char * tb_v8696 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8696; }
    { const char * tb_v8697 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8697; }
    { const char * tb_v8698 = "        for (int i = 0; i < 3; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8698; }
