    { const char * tb_v8705 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v8705; }
    { const char * tb_v8706 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v8706; }
    { const char * tb_v8707 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v8707; }
    { const char * tb_v8708 = "static const float *tb_kd_c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8708; }
    { const char * tb_v8709 = "static int tb_kd_cmp(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8709; }
    { const char * tb_v8710 = "    float x = tb_kd_c[3 * *(const uint32_t *)a + tb_kd_ax], y = tb_kd_c[3 * *(const uint32_t *)b + tb_kd_ax];\n"; *(const char * *)tb_grow(v_lines) = tb_v8710; }
    { const char * tb_v8711 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8711; }
    { const char * tb_v8712 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8712; }
