    { const char * tb_v8716 = "        m->chr[2 * c] = *at; m->chr[2 * c + 1] = n; *at += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8716; }
    { const char * tb_v8717 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8717; }
    { const char * tb_v8718 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8718; }
    { const char * tb_v8719 = "    float lo[3] = { 1e30f, 1e30f, 1e30f }, hi[3] = { -1e30f, -1e30f, -1e30f };\n"; *(const char * *)tb_grow(v_lines) = tb_v8719; }
    { const char * tb_v8720 = "    for (long long i = 0; i < n; i++) for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8720; }
