    { const char * tb_v8733 = "    double lo[3] = { 1e300, 1e300, 1e300 }, hi[3] = { -1e300, -1e300, -1e300 }, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8733; }
    { const char * tb_v8734 = "    for (long long t = t0; t < t0 + tn; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8734; }
