    { const char * tb_v8736 = "        for (int k = 0; k < 3; k++) { if (p[k] < lo[k]) lo[k] = p[k]; if (p[k] > hi[k]) hi[k] = p[k]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8736; }
