    { const char * tb_v8875 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v8875; }
    { const char * tb_v8876 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v8876; }
    { const char * tb_v8877 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
