    { const char * tb_v8897 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8897; }
    { const char * tb_v8898 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8898; }
