    { const char * tb_v8901 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8901; }
    { const char * tb_v8902 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8902; }
    { const char * tb_v8903 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8903; }
    { const char * tb_v8904 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
