    { const char * tb_v8919 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
    { const char * tb_v8923 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8923; }
    { const char * tb_v8924 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8924; }
    { const char * tb_v8925 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v8925; }
    { const char * tb_v8926 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8926; }
    { const char * tb_v8927 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8927; }
    { const char * tb_v8928 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v8928; }
    { const char * tb_v8929 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8929; }
    { const char * tb_v8930 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8930; }
    { const char * tb_v8931 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
    { const char * tb_v8932 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8932; }
    { const char * tb_v8933 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8933; }
    { const char * tb_v8934 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8934; }
    { const char * tb_v8935 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8935; }
    { const char * tb_v8936 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8936; }
    { const char * tb_v8937 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v8937; }
    { const char * tb_v8938 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v8938; }
    { const char * tb_v8939 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v8939; }
    { const char * tb_v8940 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v8940; }
    { const char * tb_v8941 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v8941; }
    { const char * tb_v8942 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v8942; }
    { const char * tb_v8943 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8943; }
    { const char * tb_v8944 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8944; }
    { const char * tb_v8945 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8945; }
    { const char * tb_v8946 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8946; }
    { const char * tb_v8947 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v8947; }
    { const char * tb_v8948 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v8948; }
    { const char * tb_v8949 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8949; }
    { const char * tb_v8950 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8950; }
    { const char * tb_v8951 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v8951; }
    { const char * tb_v8952 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8952; }
    { const char * tb_v8953 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8953; }
    { const char * tb_v8954 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v8954; }
    { const char * tb_v8955 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v8955; }
    { const char * tb_v8956 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v8956; }
    { const char * tb_v8957 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8957; }
    { const char * tb_v8958 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8958; }
    { const char * tb_v8959 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8959; }
    { const char * tb_v8960 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8960; }
    { const char * tb_v8961 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8961; }
    { const char * tb_v8962 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v8962; }
    { const char * tb_v8963 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8963; }
    { const char * tb_v8964 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v8964; }
    { const char * tb_v8965 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v8965; }
    { const char * tb_v8966 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8966; }
    { const char * tb_v8967 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8967; }
    { const char * tb_v8968 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8968; }
    { const char * tb_v8969 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v8969; }
    { const char * tb_v8970 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8970; }
    { const char * tb_v8971 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8971; }
    { const char * tb_v8972 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8972; }
    { const char * tb_v8973 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v8973; }
    { const char * tb_v8974 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8974; }
    { const char * tb_v8975 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8975; }
    { const char * tb_v8976 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8976; }
    { const char * tb_v8977 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8977; }
    { const char * tb_v8978 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8978; }
    { const char * tb_v8979 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8979; }
    { const char * tb_v8980 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8980; }
    { const char * tb_v8981 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8981; }
    { const char * tb_v8982 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8982; }
    { const char * tb_v8983 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8983; }
