    { const char * tb_v8985 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8985; }
    { const char * tb_v8986 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v8986; }
    { const char * tb_v8987 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8987; }
    { const char * tb_v8988 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8988; }
    { const char * tb_v8989 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8989; }
    { const char * tb_v8990 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8990; }
    { const char * tb_v8991 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8991; }
    { const char * tb_v8992 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v8992; }
    { const char * tb_v8993 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8993; }
    { const char * tb_v8994 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8994; }
    { const char * tb_v8995 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8995; }
    { const char * tb_v8996 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8996; }
    { const char * tb_v8997 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8997; }
    { const char * tb_v8998 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v8998; }
    { const char * tb_v8999 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8999; }
    { const char * tb_v9000 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9000; }
    { const char * tb_v9001 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9001; }
    { const char * tb_v9002 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9002; }
    { const char * tb_v9003 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9003; }
    { const char * tb_v9004 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9004; }
    { const char * tb_v9005 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v9005; }
    { const char * tb_v9006 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9006; }
    { const char * tb_v9007 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v9007; }
    { const char * tb_v9008 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v9008; }
    { const char * tb_v9009 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v9009; }
    { const char * tb_v9010 = "    float dm = (mt - tb_mg) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9010; }
    { const char * tb_v9011 = "    for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9011; }
    { const char * tb_v9012 = "        tb_mg += dm;\n"; *(const char * *)tb_grow(v_lines) = tb_v9012; }
    { const char * tb_v9013 = "        float l = out[2 * i] * tb_mg, r = out[2 * i + 1] * tb_mg;\n"; *(const char * *)tb_grow(v_lines) = tb_v9013; }
    { const char * tb_v9014 = "        float pk = fabsf(l) > fabsf(r) ? fabsf(l) : fabsf(r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9014; }
    { const char * tb_v9015 = "        if (pk * tb_lim > 0.98f) tb_lim = 0.98f / pk;\n"; *(const char * *)tb_grow(v_lines) = tb_v9015; }
    { const char * tb_v9016 = "        else tb_lim += (1 - tb_lim) * 0.0002f;\n"; *(const char * *)tb_grow(v_lines) = tb_v9016; }
    { const char * tb_v9017 = "        l *= tb_lim; r *= tb_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v9017; }
    { const char * tb_v9018 = "        out[2 * i] = l > 1 ? 1 : l < -1 ? -1 : l;\n"; *(const char * *)tb_grow(v_lines) = tb_v9018; }
    { const char * tb_v9019 = "        out[2 * i + 1] = r > 1 ? 1 : r < -1 ? -1 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9019; }
    { const char * tb_v9020 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9020; }
    { const char * tb_v9021 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9021; }
    { const char * tb_v9022 = "static long long tb_snd_now_us(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9022; }
    { const char * tb_v9023 = "    struct timespec ts;\n"; *(const char * *)tb_grow(v_lines) = tb_v9023; }
