    { const char * tb_v9025 = "    return (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v9025; }
    { const char * tb_v9026 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9026; }
    { const char * tb_v9027 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v9027; }
    { const char * tb_v9028 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9028; }
    { const char * tb_v9029 = "    float buf[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9029; }
    { const char * tb_v9030 = "    short pcm[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9030; }
    { const char * tb_v9031 = "    unsigned long long bytes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9031; }
    { const char * tb_v9032 = "    long long next = tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v9032; }
    { const char * tb_v9033 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9033; }
    { const char * tb_v9034 = "        tb_mix(buf, TB_SBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v9034; }
    { const char * tb_v9035 = "        if (f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9035; }
    { const char * tb_v9036 = "            for (int i = 0; i < TB_SBLOCK * 2; i++) pcm[i] = (short)lrintf(buf[i] * 32767);\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
