    { const char * tb_v9204 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v9204; }
    { const char * tb_v9205 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
    { const char * tb_v9211 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
