    { const char * tb_v9216 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
