    { const char * tb_v9220 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
