    { const char * tb_v9232 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
    { const char * tb_v9233 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v9233; }
    { const char * tb_v9234 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9234; }
