    { const char * tb_v9246 = "            const unsigned char *q = data + i * bpf + (uint32_t)k * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v9246; }
    { const char * tb_v9247 = "            float v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9247; }
    { const char * tb_v9248 = "            if (tag == 3) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9248; }
