    { const char * tb_v9253 = "            else if (bits == 24) v = (float)((int32_t)((uint32_t)q[0] << 8 | (uint32_t)q[1] << 16 | (uint32_t)q[2] << 24) >> 8) / 8388608.0f;\n"; *(const char * *)tb_grow(v_lines) = tb_v9253; }
    { const char * tb_v9254 = "            else v = (float)((int32_t)tb_le32(q) / 2147483648.0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
