    { const char * tb_v9288 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "// голос по номеру (под замком); старый номер (голос уже другой) — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "static tb_voice *tb_voice_at(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
