    { const char * tb_v9306 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9306; }
    { const char * tb_v9307 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v9307; }
    { const char * tb_v9308 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9308; }
    { const char * tb_v9309 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9309; }
    { const char * tb_v9310 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9310; }
